"""Reviewed hub + Japanese beginner task, with explicit source/edition boundaries."""
from build_pokebonk import ext, ref, table, section
P='/survivor-ace/'
A='/assets/survivor-ace/'
JP=P+'ja/beginners-guide/'
S=[('https://play.google.com/store/apps/details?hl=en&id=com.survivor.ace','Google Play · Gorilla Studio','Store identity and mobile gameplay; checked 2026-10-28.'),('https://gamesakidori.com/dada-ace/dada-ace-beginner-guide/','ゲーム先取り · 2026-10-27','日本版iPhone約30分という作者の範囲。開局・強化例。本站未プレイ。'),('https://labs.invenglobal.com/articles/27613/simple-controls-precise-firepower-survivor-ace','Inven · Kobee · 2026-10-22','Author gameplay account; client build unspecified. Not an independent confirmation of the Japanese client.')]
def sources(ja=False):
 descriptions=(['ストアのゲーム識別と概要。2026-10-28確認。','作者による日本版iPhone約30分の記録。初期武器と装備の例。当サイトの実測ではありません。','Kobeeの体験記事。版は未記載。日本版の初期状態を確認した資料ではありません。'] if ja else ['Store identity and mobile gameplay; checked 2026-10-28.','Author reports about 30 minutes with the Japanese iPhone edition, with weapon and equipment examples. Not our playtest.','Kobee’s gameplay account; client build unspecified. Not an independent confirmation of the Japanese client.'])
 return '<section class="sources" id="sources"><h2>'+('出典と適用範囲' if ja else 'Sources & edition limits')+'</h2><ol>'+''.join(f'<li id="source-{i}">{ext(u,l)} — {descriptions[i-1]}</li>' for i,(u,l,d) in enumerate(S,1))+'</ol><a class="back" href="#guide">'+('本文に戻る ↑' if ja else 'Back to guide ↑')+'</a></section>'

def hub(shell):
 intro=f'''<header class="hero" id="guide"><div><span class="tag">Independent flight guide · Megabonk.org</span><h1>Survivor: Ace<br>Guides</h1><p class="lead">Fly, dodge and build your next attempt. Survivor: Ace is Gorilla Studio’s mobile aerial roguelike, also called 噠噠戰機, ダダエース and 탕탕 에이스. It is a separate game from Survivor.io.{ref(1)}</p><div class="actions"><a class="button" href="#start">Start your first run ↓</a><a class="button secondary" href="#codes">Find code guides ↓</a></div><p class="meta">Checked October 28, 2026 · Source-based, not our playtest</p></div><figure class="hero-art"><img src="{A}flight-loop.svg" width="1200" height="630" alt="Three decisions: dodge, choose an offered upgrade, then prepare the next attempt"><figcaption>Original editorial diagram of the decision loop. Not game footage.</figcaption></figure></header>'''
 start=f'''<p>Start with the mobile client linked from {ext('https://www.survivor-ace.com/','Survivor: Ace official website')}. Check the name before following instructions for the older game.</p><ol><li><strong>Move first.</strong> Drag to steer while attacks fire automatically.</li><li><strong>Read the draft.</strong> Choose among the upgrades actually offered, rather than expecting a fixed build order.</li><li><strong>Review the failure.</strong> Separate being hit from leaving enemies alive, then decide what the next attempt needs.</li></ol><p>This sequence combines the authors’ examples into a review method; it is not a tested clear route.{ref(2)}{ref(3)}</p><p><a href="{JP}" lang="ja">日本語：序盤の進め方と武器選び →</a></p>'''
 choices=table(['What you notice','Decision to review'],[['Your attacks miss moving targets','Check whether an offered attack tracks targets or requires a forward line.'],['Your current attack connects, but enemies remain','Compare an upgrade to that weapon with a new attack; more weapon names alone do not settle the choice.'],['You lose HP before damage becomes the problem','Compare the available survival effect with another damage pick.']])+f'<p>This is a conditional reading checklist, not a weapon tier list. The Japanese examples and Inven’s cannon example describe different starts; neither establishes everyone’s default weapon.{ref(2)}{ref(3)}</p>'
 prep=table(['During a run','Between attempts'],[['A choice from the current randomized draft','An equipment change whose displayed cost and effect you can inspect'],['Useful for the situation on screen','A separate decision before flying again']])+f'<p>Do not turn a missed random offer into an assumed equipment problem. First note what failed, then inspect the relevant effect instead of spending across every system.{ref(2)}{ref(3)}</p>'
 zh='<div class="flight-note" lang="zh-Hant"><h3>繁中快速入門</h3><p>先認準噠噠戰機，再依畫面提供的升級選項作決定。局內武器／技能選擇與局外裝備養成要分開；輸掉後先記下是被彈幕擊中，還是敵人清不掉，再調整下一次嘗試。</p><a href="'+P+'zh-hant/codes/">禮包碼與輸入位置 →</a></div>'
 cards=f'''<section id="guides"><h2>Choose your next task</h2><div class="hub-card-grid"><div class="card"><span class="number">01 / START</span><h3>日本語・序盤攻略</h3><p>初期武器、候補の読み方、装備との違いを確認。</p><a href="{JP}" lang="ja">序盤ガイドを開く →</a></div><div class="card"><span class="number">02 / CODES</span><h3>繁中禮包碼</h3><p>輸入方法、來源期限與獎勵差異；未實兌。</p><a href="{P}zh-hant/codes/" lang="zh-Hant">查看禮包碼 →</a></div><div class="card"><span class="number">03 / CODES</span><h3>日本語・コード</h3><p>掲載情報、入力場所と期限を照合。</p><a href="{P}ja/codes/" lang="ja">コードを確認 →</a></div></div></section>'''
 codes=f'<p>Codes and their deadlines change. Use the language-specific guides for reported strings and redemption steps; no code on this website is labeled as redeemed by us.</p><p><a href="{P}zh-hant/codes/" lang="zh-Hant">噠噠戰機禮包碼 →</a> · <a href="{P}ja/codes/" lang="ja">ダダエースのコード →</a></p>'
 helptext=f'<p>For account, purchase or missing-reward issues, use {ext(S[0][0],"Google Play · App support")}. We cannot credit rewards or recover accounts. For public discussion, {ext("https://forum.gamer.com.tw/B.php?bsn=86353","Bahamut · 噠噠戰機 board")} is a separate community; its activity could not be verified during this review.</p><p>Use {ext("https://www.survivor-ace.com/","Survivor: Ace official website")} for current store and community links. Avoid treating a forum answer or a translated guide as a developer guarantee.</p>'
 body=intro+cards+'<div class="hub-sections prose">'+section('start','Start here: one useful first loop',start)+zh+section('weapons','Read a weapon choice by the problem it solves',choices)+section('progression','Keep the two upgrade decisions separate',prep)+section('codes','Code guides & redemption',codes)+section('help','Official help & community',helptext)+sources()+'</div>'
 return P,shell(P,'Survivor: Ace Guides — Getting Started & Codes','Start Survivor: Ace with a clear first-run checklist, upgrade decision help, Japanese beginner guidance and source-qualified Chinese and Japanese codes.',body,content=True,image=A+'flight-loop.png')

def beginner(shell):
 parts=[]
 parts.append(('first-run','最初の一周で確認すること',f'<p>指で動かし、自動射撃が届く向きと安全な場所を確認します。候補が出たら「新しい攻撃」「今の攻撃の強化」「耐久」のどれが変わるかを分けて読み、終了後に不足した点を一つ記録します。これは出典を組み合わせた判断手順で、クリア保証ではありません。{ref(2)}{ref(3)}</p>'))
 weapons=table(['日本版記事の選択例','攻撃の違い','選ぶ前の確認'],[['高エネルギーレーザー','前方を貫通','敵を前方に捉え続けられるか'],['灼熱ビーム','近い敵への継続攻撃','優先して狙いたい敵に届くか'],['フロストブレード','自動追尾','移動しながら当てたいか']])+f'<p>ゲーム先取りが記録した日本版iPhoneの序盤例です。どの機体・章でもこの三択になるとは確認できていません。Invenの作者は機炮を主軸にした別の例を紹介しており、共通の初期装備とは断定しません。手元の候補名と説明を優先してください。{ref(2)}{ref(3)}</p>'
 parts.append(('weapons','初期武器は攻撃範囲から比べる',weapons))
 draft=table(['今困っていること','提示された候補の見方','避けたい思い込み'],[['敵に当たるが倒し切れない','その武器の強化と新しい攻撃の対象・範囲を比較','武器数を増やせば必ず強くなる'],['敵に狙いを合わせにくい','追尾と前方向の攻撃を区別','別の版の固定ビルドをそのまま再現できる'],['先にHPが尽きる','現在の候補に耐久効果があるか読む','火力の強化で現在のHPも回復する'],['欲しい候補が出ない','今ある三択で補える不足を一つ選ぶ','攻略例と同じ順番で引ける']])+f'<p>上表は編集部の選択チェック表です。ランダム候補の確率や出現保証は未確認。Invenの弱点表示と単一武器強化の体験は参考になりますが、日本版の数値や万能な最強構成を証明しません。{ref(3)}</p>'
 parts.append(('draft','武器を増やす？ 今の武器を強化する？',draft))
 equip=table(['判断する場所','比べるもの','次の確認'],[['戦闘中','表示されたスキル・武器・耐久候補','今回の敵と現在の攻撃に合うか'],['戦闘後の装備画面','強化前後に表示される効果と消費素材','不足を補える部位か、費用を払う価値があるか']])+f'<p>ゲーム先取りは装備画面でHP・攻撃力の変化を記録しています。まず手元の変化量を確認し、鍵付きの効果を最初から使えるものとして数えないでください。公開例の数値を全レベルに当てはめず、複数の育成先へ一度に資源を使う前に、次の一段階を比較しましょう。{ref(2)}</p>'
 parts.append(('equipment','局内の選択と局外の装備を分ける',equip))
 retry='<ol><li>負けた時点、残りHP、使っていた武器と選択候補をメモする。</li><li>「当たらない」「当たるが倒せない」「被弾して終わる」を区別する。</li><li>次の一回では、選び方か装備の一方を変え、同じ問題が残るか見る。</li></ol><p>これは比較しやすくするための提案です。操作練習、装備変更、候補の運は別の要因なので、一回の成功を最強構成の証拠にしません。</p>'
 parts.append(('retry','次の出撃に残すメモ',retry))
 rewards=f'<p>コードは別ページで期限と入力場所を確認できます。昔の配信開始時の抽数やイベント報酬を、今の全アカウントの受取保証として扱わないでください。</p><p><a href="{P}ja/codes/">ダダエースのコード・入力方法 →</a></p><p>ゲームが開かない、アカウントや購入の問題は、{ext(S[0][0],"Google Play · アプリのサポート")}へ。このページは通信・公会エラーの修復手順ではありません。</p>'
 parts.append(('rewards','コードと困ったときの窓口',rewards))
 toc='<aside class="toc" aria-label="目次"><strong>目次</strong>'+''.join(f'<a href="#{i}">{t}</a>' for i,t,_ in parts)+'<a href="#sources">出典</a></aside>'
 body=f'<nav class="crumbs" aria-label="Breadcrumb"><a href="{P}">Survivor: Ace</a> / 日本語・序盤攻略</nav><header class="article-head" id="guide"><span class="tag">ダダエース · 非公式ガイド</span><h1>ダダエース序盤攻略：武器選びと育成の進め方</h1><p class="answer">初期武器は攻撃範囲、戦闘中の強化は今の不足、戦闘後の装備は表示される効果と費用で比べます。「毎回この武器を引く」という固定手順にせず、候補と失敗した原因から次の一手を決めましょう。</p><p class="meta">Megabonk.org editors · 2026-10-28 · 出典比較。当サイトでのプレイ・性能比較テストなし</p></header><div class="article-layout"><article class="prose">'+''.join(section(*x) for x in parts)+sources(True)+f'<section class="related"><h2>次に見るページ</h2><a href="{P}ja/codes/">日本語コード →</a><a href="{P}#guides">Survivor: Ace ガイド一覧 →</a></section></article>'+toc+'</div>'
 return JP,shell(JP,'ダダエース序盤攻略｜武器選びと装備育成','ダダエースの初期武器、ランダムな強化候補、戦闘後の装備を分けて比較。日本版と海外の出典の違い、負けた後に確認する項目を整理します。',body,lang='ja',content=True)

def make_pages(shell):return [hub(shell),beginner(shell)]
